                category=UserWarning,
            )
            mode = RunMode.MULTIRUN
            overrides.extend(["hydra.mode=MULTIRUN"])

    if mode == RunMode.RUN:
        run_and_report(
            lambda: hydra.run(
                config_name=config_name,
                task_function=task_function,
                overrides=overrides,
            )
        )
    else:
        run_and_report(
            lambda: hydra.multirun(
                config_name=config_name,
                task_function=task_function,
                overrides=overrides,
            )
        )


